/* eslint-disable */
import React, { useMemo, useState } from "react";

/**
 * items: [{ img, title, excerpt, href }]
 * Ordre attendu:
 *   0 = fond (New Deal), 1 = milieu (SIM), 2 = avant (portrait/citation)
 */
export default function NewsStack({
    items = [],
    className = "",
}) {
    const [hovered, setHovered] = useState(null);

    // Disposition type Figma : cascade droite -> gauche en descendant
    //  - On positionne avec `right` (et non `left`)
    //  - Tailles légèrement différentes par couche pour coller au visuel
    const layers = useMemo(
        () => [
            // FOND (ensuite on empile par-dessus)
            {
                top: 0,
                right: 0,
                width: 520,
                height: 300,
                rotate: 0,
                z: 10,
            },
            // MILIEU (un peu plus bas et décalé vers la gauche)
            {
                top: 36,
                right: 42,
                width: 500,
                height: 240,
                rotate: 1.5,
                z: 20,
            },
            // AVANT (encore plus bas & plus à gauche, plus haut)
            {
                top: 90,
                right: 84,
                width: 520,
                height: 360,
                // rotate: -0.8,
                rotate: 0,

                z: 30,
            },
        ],
        []
    );

    const containerSize = useMemo(() => {
        // Hauteur totale nécessaire pour contenir la carte avant
        const last = layers[layers.length - 1];
        return {
            width: layers[0].width + layers[0].right, // suffit, on contraint par max-width plus bas
            height: last.top + last.height + 4,
        };
    }, [layers]);

    const hoverStyle = (i) => {
        const is = hovered === i;
        return {
            transform: `translate3d(${is ? "-6px" : "0"},${is ? "-6px" : "0"},0) rotate(${layers[i].rotate}deg) scale(${is ? 1.03 : 1})`,
            zIndex: is ? 50 : layers[i].z,
            boxShadow: is
                ? "0 22px 56px rgba(0,0,0,.34)"
                : "0 14px 32px rgba(0,0,0,.22)",
            filter: is ? "saturate(1.06) contrast(1.02)" : "saturate(.92)",
            transition: "transform .28s cubic-bezier(.2,.8,.2,1), box-shadow .28s ease, filter .28s ease",
        };
    };

    return (
        <div className={`relative ${className}`}>
            <div
                className="relative"
                style={{
                    width: "100%",
                    maxWidth: layers[0].width + 100, // marge pour le décalage à gauche
                    height: containerSize.height,
                }}
            >
                {items.slice(0, 3).map((it, i) => (
                    <article
                        key={i}
                        className="absolute rounded-xl overflow-hidden bg-white cursor-pointer will-change-transform"
                        style={{
                            top: layers[i].top,
                            right: layers[i].right,
                            width: layers[i].width,
                            height: layers[i].height,
                            ...hoverStyle(i),
                        }}
                        onMouseEnter={() => setHovered(i)}
                        onMouseLeave={() => setHovered(null)}
                    >
                        <a href={it.href || "#"} className="block w-full h-full relative" aria-label={it.title}>
                            <img
                                src={it.img}
                                alt={it.title}
                                className="absolute inset-0 w-full h-full object-cover"
                                loading="lazy"
                            />

                            {/* Liseré bleu à droite */}
                            <div className="absolute top-3 right-3 h-[88%] w-1 rounded bg-[#5aa4ff]" />

                            {/* Dégradé + texte : visible en permanence sur la carte avant (i===2), sinon au hover */}
                            <div
                                className={`absolute inset-0 flex items-end p-5 text-white ${hovered === i || i === 2 ? "opacity-100" : "opacity-0"
                                    }`}
                                style={{
                                    background:
                                        "linear-gradient(to top, rgba(0,0,0,.72) 0%, rgba(0,0,0,.05) 60%, rgba(0,0,0,0) 100%)",
                                    transition: "opacity .2s ease",
                                }}
                            >
                                <div className="w-full">
                                    <h4
                                        className="text-lg font-semibold leading-tight"
                                        style={{
                                            display: "-webkit-box",
                                            WebkitLineClamp: 2,
                                            WebkitBoxOrient: "vertical",
                                            overflow: "hidden",
                                        }}
                                    >
                                        {it.title}
                                    </h4>
                                    <p
                                        className="text-sm opacity-95 mt-1"
                                        style={{
                                            display: "-webkit-box",
                                            WebkitLineClamp: 2,
                                            WebkitBoxOrient: "vertical",
                                            overflow: "hidden",
                                        }}
                                    >
                                        {it.excerpt}
                                    </p>
                                </div>
                            </div>
                        </a>
                    </article>
                ))}
            </div>
        </div>
    );
}
